const sha=(value:string|Uint8Array)=>new Bun.CryptoHasher('sha256').update(value).digest('hex');

async function evidence(){
 const files={mainText:'.superpowers/m78-hosted-continuation4.jsonl',diagnosticText:'.superpowers/m78-hosted-continuation4-diagnostics.jsonl',baselineResultText:'evaluations/research-qa/m78-continuation4-baseline-independent-result.json',exerciseGateText:'.superpowers/m78-continuation4-exercise-gate.json',providerObservationText:'evaluations/research-qa/m78-continuation4-failure-http-observation.json',browserObservationText:'evaluations/research-qa/m78-continuation4-browser-http-observation.json',failureReviewText:'evaluations/research-qa/m78-continuation4-exercise-failure-qa-result.json'}as const,loaded:any={};for(const[key,path]of Object.entries(files))loaded[key]=await readFile(path,'utf8');
 const pins=Array.from({length:173},(_,index)=>{const path=index===0?'tools/staging/check-m78-continuation4-readonly-recovery.ts':`synthetic://current/${index}`,text=`pin-${index}`;return{path,text,sha256:sha(text)}}),currentSourcePins=pins.map(({path,sha256})=>({path,sha256})),currentSourceGateText=JSON.stringify({status:'m78_continuation4_readonly_recovery_source_admitted',historicalExerciseGateSha256:'9fe233c964b8c40f6c7a9871eecf75a318e7a800f2ec14570c6803288ff9dce7',sourcePins:currentSourcePins,sourcePinsSha256:sha(canonical(currentSourcePins)),runtime:{commit:'a'.repeat(40),deploymentId:'synthetic-deployment'}});
 return{...loaded,currentSourcePins,currentSourceGateText,load:async(path:string)=>pins.find(pin=>pin.path===path)!.text}as RecoveryAdmission;
}
function memoryIO(existing:string|null=null){const values=new Map<string,string>();if(existing)values.set(M78_READONLY_RECOVERY_PATHS.observation,existing);const io:RecoveryIO={read:async path=>values.get(path)??null,append:async(path,text,exclusive)=>{if(exclusive&&values.has(path))throw Error('exists');values.set(path,(values.get(path)??'')+text)}};return{io,values}}
function currentGraph(mainText:string){const events=mainText.trimEnd().split('\n').map(line=>JSON.parse(line)),identities=events.filter(event=>event.kind==='post_verified').map(event=>event.data.verifiedIdentity),reports=identities.filter(identity=>identity.reportSha256),processReports=reports.filter(identity=>events.find(event=>event.kind==='post_verified'&&event.data.verifiedIdentity.id===identity.id)!.data.name.includes('process')),inventoryReports=reports.filter(identity=>!processReports.includes(identity));return{identities,reports,scope1:{extra:identities,process:{versions:[],reports:processReports},inventory:{versions:[],reports:inventoryReports}},registers:{corporate:{versions:[]},gas:{worksheets:[]},mobile:{worksheets:[]},fleet:{versions:[],reports:[]},diesel:{worksheets:[]},equipment:{versions:[],reports:[]},fugitive:{worksheets:[],population:{versions:[],reports:[]}}}}}
function harness(admission:RecoveryAdmission,options:{existing?:string;missingIdentity?:boolean;decodeFailure?:boolean;mutatingAuth?:boolean;wrongSubject?:boolean;openFailure?:boolean;oversized?:boolean;closeFailure?:boolean;journalFailure?:boolean;diagnosticHeaderFailure?:boolean;diagnosticLogoutFailures?:boolean;diagnosticPhaseFailure?:boolean;invalidLogoutScope?:boolean}={}){
